let binaryData = $input.first()?.binary;
if (!binaryData) {
  try {
    binaryData = $('When chat message received').item.binary;
  } catch (e) {
    binaryData = null;
  }
}

if (!binaryData || Object.keys(binaryData).length === 0) {
  return [{ 
    json: { 
      text: "No attached files found. Please try uploading again.",
      error: true
    } 
  }];
}

const results = [];
const rejected = [];

for (const key of Object.keys(binaryData)) {
  const file = binaryData[key];
  const fileName = (file.fileName || 'unknown');
  const fileNameLower = fileName.toLowerCase();
  const mimeType = file.mimeType || '';

  let fileType = null;

  // PDF
  if (mimeType.includes('pdf') || fileNameLower.endsWith('.pdf')) {
    fileType = 'pdf';
  }

  // TXT
  else if (
    mimeType.includes('text') ||
    fileNameLower.endsWith('.txt') 
  ) {
    fileType = 'txt';
  }

  // DOCX
  else if (
    mimeType.includes('wordprocessingml') ||
    fileNameLower.endsWith('.docx') 
  ) {
    fileType = 'docx';
  }

  // CSV
  else if (
    mimeType.includes('csv') ||
    fileNameLower.endsWith('.csv')
  ) {
    fileType = 'csv';
  }

  // XLS
  else if (
    mimeType.includes('vnd.ms-excel') ||
    fileNameLower.endsWith('.xls')
  ) {
    fileType = 'xls';
  }

  // XLSX
  else if (
    mimeType.includes('spreadsheetml') ||
    fileNameLower.endsWith('.xlsx')
  ) {
    fileType = 'xlsx';
  }

  // Unsupported Files
  else {
    rejected.push(fileName);
    continue;
  }

  results.push({
    json: {
      fileName: fileName,
      mimeType: mimeType,
      fileType: fileType
    },
    binary: {
      data: file
    }
  });
}

if (results.length === 0) {
  return [{
    json: {
      error: true,
      text: `Unsupported file type(s): ${rejected.join(', ')}. Supported formats are: PDF, TXT, CSV, XLS, XLSX, DOCX.`
    }
  }];
}

if (rejected.length > 0) {
  results[0].json.warning = `Skipped unsupported file(s): ${rejected.join(', ')}`;
}

return results;

