const items = $input.all();
const documentToolData = $('File Type').all();
const results = [];

const fileNameMap = {};
documentToolData.forEach((doc, index) => {
  fileNameMap[index] = doc.json.fileName || `Document_${index + 1}`;
});

items.forEach((item, fileIndex) => {
  let text = '';
  let fileName = fileNameMap[fileIndex] || 'Unknown Document';

  if (item.json.data && Array.isArray(item.json.data)) {
    text = item.json.data
      .map((page, pageIndex) => {
        const pageText = (page.text || '').trim();

        if (!pageText || pageText.length < 5) return null;

        return `[Page ${pageIndex + 1}]\n${pageText}`;
      })
      .filter(page => page !== null)
      .join('\n\n');
  }
  else if (item.json.text) {
    text = (item.json.text || '').trim();
    fileName = item.json.fileName || fileName;
  }

  if (!text || text.trim().length < 10) return;

  results.push({
    json: {
      fileName: fileName,
      fileContent: text
    }
  });
});

return results;

