const items = $input.all();
const fileTypeData = $('File Type').all();

const fileNameMap = {};
fileTypeData.forEach((doc, index) => {
  fileNameMap[index] = doc.json.fileName || `Document_${index + 1}`;
});

const fileGroups = {};

items.forEach((item, index) => {
  const fileName = fileNameMap[index] || `Document_${index + 1}`;

  if (!fileGroups[fileName]) {
    fileGroups[fileName] = [];
  }

  const text = item.json.data || item.json.text || '';
  if (text.trim()) {
    fileGroups[fileName].push(text);
  }
});

// Return one item per file
return Object.entries(fileGroups).map(([fileName, contents]) => ({
  json: {
    fileName: fileName,
    fileContent: contents.join('\n')
  }
}));

