const helperItems = $('helper').all();

const TOKEN_LIMIT = 7000;
const CHARS_PER_TOKEN = 4;
const MAX_CHARS = Math.floor(TOKEN_LIMIT * CHARS_PER_TOKEN * 0.9);
const OVERLAP_CHARS = Math.floor(MAX_CHARS * 0.05); // 5% overlap

const results = [];

helperItems.forEach((item) => {
  const text = typeof item.json.fileContent === 'string'
    ? item.json.fileContent
    : JSON.stringify(item.json.fileContent || '');
  const fileName = item.json.fileName || 'Unknown Document';
  const estimatedTokens = Math.ceil(text.length / CHARS_PER_TOKEN);

  if (!text.trim()) return;

  // Small file, pass directly 
  if (estimatedTokens <= TOKEN_LIMIT) {
    results.push({
      json: {
        filename: fileName,
        content: text,
        estimated_tokens: estimatedTokens,
        is_split: false,
        chunk_index: 1,
        total_chunks: 1,
        mode: 'direct'
      }
    });
    return;
  }

  // Large file, split with overlap
  const chunks = [];
  let start = 0;

  while (start < text.length) {
    let end = start + MAX_CHARS;

    if (end < text.length) {
      const nearestSpace = text.lastIndexOf(' ', end);
      if (nearestSpace > start) end = nearestSpace;
    }

    const chunkText = text.slice(start, end).trim();
    if (chunkText.length > 0) chunks.push(chunkText);

    start = end - OVERLAP_CHARS;

    const nextSpace = text.indexOf(' ', start);
    if (nextSpace !== -1 && nextSpace < end) start = nextSpace + 1;
  }

  const totalChunks = chunks.length;

  chunks.forEach((chunkText, index) => {
    const chunkIndex = index + 1;
    results.push({
      json: {
        filename: fileName,
        content: chunkText,
        estimated_tokens: Math.ceil(chunkText.length / CHARS_PER_TOKEN),
        is_split: true,
        chunk_index: chunkIndex,
        total_chunks: totalChunks,
        mode: chunkIndex === totalChunks ? 'final' : 'partial'
      }
    });
  });
});

return results;

const helperItems = $('helper').all();

const CHARS_PER_TOKEN = 4;
const PREVIEW_TOKENS = 1000;
const PREVIEW_CHARS = PREVIEW_TOKENS * CHARS_PER_TOKEN; // 4000 chars
const MAX_ROWS = 5;

const results = [];

helperItems.forEach((item) => {
  const fileName = item.json.fileName || 'Unknown Document';
  const fileNameLower = fileName.toLowerCase();
  const rawContent = item.json.fileContent;

  let text = '';
  let note = '';

  // Data Set files
  if (
    fileNameLower.endsWith('.csv') ||
    fileNameLower.endsWith('.xls') ||
    fileNameLower.endsWith('.xlsx')
  ) {
    if (Array.isArray(rawContent)) {
      const rows = rawContent.slice(0, MAX_ROWS);
      if (rawContent.length > MAX_ROWS)
        note = `[Preview: first ${MAX_ROWS} of ${rawContent.length} rows]`;
      text = JSON.stringify(rows);
    } else {
      text = typeof rawContent === 'string' ? rawContent : JSON.stringify(rawContent || '');
    }
  }
  // PDF, TXT and DOCX files
  else {
    const full = typeof rawContent === 'string'
      ? rawContent
      : JSON.stringify(rawContent || '');

    if (full.length > PREVIEW_CHARS) {
      text = full.slice(0, PREVIEW_CHARS);

      const lastSpace = text.lastIndexOf(' ');
      if (lastSpace > 0) text = text.slice(0, lastSpace);
      note = `[Preview: first ${PREVIEW_TOKENS} tokens of document]`;
    } else {
      text = full;
    }
  }

  if (!text.trim()) return;

  if (note) text = `${note}\n\n${text}`;

  results.push({
    json: {
      filename: fileName,
      content: text,
      estimated_tokens: Math.ceil(text.length / CHARS_PER_TOKEN),
      mode: 'direct'
    }
  });
});

return results;

const helperItems = $('helper').all();

const TOKEN_LIMIT = 4000;
const CHARS_PER_TOKEN = 4;
const MAX_CHARS = Math.floor(TOKEN_LIMIT * CHARS_PER_TOKEN * 0.9);
const MAX_ROWS = 10;
const results = [];

helperItems.forEach((item) => {
  const fileName = item.json.fileName || 'Unknown Document';
  const fileNameLower = fileName.toLowerCase();
  const rawContent = item.json.fileContent;

  let text = '';
  let trimmed = false;

  if (
    fileNameLower.endsWith('.csv') ||
    fileNameLower.endsWith('.xls') ||
    fileNameLower.endsWith('.xlsx')
  ) {
    if (Array.isArray(rawContent)) {
      const rows = rawContent.slice(0, MAX_ROWS);
      trimmed = rawContent.length > MAX_ROWS;
      text = JSON.stringify(rows);
    } else {
      text = typeof rawContent === 'string' ? rawContent : JSON.stringify(rawContent || '');
    }
  } else {
    text = typeof rawContent === 'string'
      ? rawContent
      : JSON.stringify(rawContent || '');
  }

  if (!text.trim()) return;

  if (trimmed) {
    text = `[Note: File contains more than ${MAX_ROWS} rows. Showing first ${MAX_ROWS} rows only.]\n\n${text}`;
  }

  const estimatedTokens = Math.ceil(text.length / CHARS_PER_TOKEN);

  if (estimatedTokens <= TOKEN_LIMIT) {
    results.push({
      json: {
        filename: fileName,
        content: text,
        estimated_tokens: estimatedTokens,
        is_split: false,
        chunk_index: 1,
        total_chunks: 1,
        mode: 'direct',
        was_trimmed: trimmed
      }
    });
    return;
  }

  const chunks = [];
  let start = 0;

  while (start < text.length) {
    let end = start + MAX_CHARS;
    if (end < text.length) {
      const nearestSpace = text.lastIndexOf(' ', end);
      if (nearestSpace > start) end = nearestSpace;
    }
    const chunkText = text.slice(start, end).trim();
    if (chunkText.length > 0) chunks.push(chunkText);
    start = end + 1;
  }

  const totalChunks = chunks.length;
  chunks.forEach((chunkText, index) => {
    const chunkIndex = index + 1;
    results.push({
      json: {
        filename: fileName,
        content: chunkText,
        estimated_tokens: Math.ceil(chunkText.length / CHARS_PER_TOKEN),
        is_split: true,
        chunk_index: chunkIndex,
        total_chunks: totalChunks,
        mode: chunkIndex === totalChunks ? 'final' : 'partial',
        was_trimmed: trimmed
      }
    });
  });
});

return results;

