const items = $input.all();

const cleanKey = (key) => key.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());

const formatSection = (obj) =>
  Object.entries(obj)
    .filter(([_, v]) => v !== null && v !== undefined)
    .map(([k, v]) => `- **${cleanKey(k)}:** ${v}`)
    .join('\n');

const formatFinancials = (obj) => {
  return Object.entries(obj)
    .filter(([_, v]) => v !== null && v !== undefined)
    .map(([k, v]) => `- **${cleanKey(k)}:** &nbsp;&nbsp; ${v}`)
    .join('\n');
};

const formatLineItems = (lineItems, currency = '') => {
  const c = currency || '';
  return lineItems.map((item, i) => {
    const desc = item.description || 'Item';
    const code = item.product_code ? ` *(${item.product_code})*` : '';
    const qty = item.quantity || '-';
    const price = item.unit_price ? `${c}${item.unit_price}` : '-';
    const total = item.line_total ? `${c}${item.line_total}` : '-';
    return `**${i + 1}. ${desc}**${code}\n- Qty: ${qty} × ${price} = **${total}**`;
  }).join('\n\n');
};

const parsed = items.map(item => {
  const text = item.json.output?.text || item.json.text || item.json.output || '';

  try {
    const cleaned = text.replace(/```json|```/g, '').trim();
    const data = JSON.parse(cleaned);
    const d = data.extracted_data || {};

    let output = `# ${data.filename}\n###### Type: ${data.document_type}\n\n`;

    if (d.parties && Object.values(d.parties).some(v => v))
      output += `**Parties:**\n${formatSection(d.parties)}\n\n`;

    if (d.dates && Object.values(d.dates).some(v => v))
      output += `**Dates:**\n${formatSection(d.dates)}\n\n`;

    if (d.reference_numbers && Object.values(d.reference_numbers).some(v => v))
      output += `**Reference Numbers:**\n${formatSection(d.reference_numbers)}\n\n`;

    const currency = d.financials 
  ? (Object.entries(d.financials).find(([k]) => k === 'currency')?.[1] || '')
  : '';

  if (d.financials && Object.values(d.financials).some(v => v))
  output += `**Financials:**\n${formatFinancials(d.financials)}\n\n`;

  if (d.line_items && d.line_items.length)
  output += `**Line Items:**\n\n${formatLineItems(d.line_items, currency)}\n\n`;

    if (d.payment_details && Object.values(d.payment_details).some(v => v))
      output += `**Payment Details:**\n${formatSection(d.payment_details)}\n\n`;

    if (data.notes)
      output += `**Notes:** ${data.notes}`;

    return output;

  } catch (e) {
    return text;
  }
}).join('\n\n---\n\n');

return [{ json: { message: parsed } }];

const mammoth = require('mammoth');

const items = $input.all();
const results = [];

for (const item of items) {
  const binary = item.binary || {};
  const binaryKey = Object.keys(binary)[0];

  if (!binaryKey) continue;

  const fileName = binary[binaryKey]?.fileName || 'Unknown.docx';
  const buffer = await this.helpers.getBinaryDataBuffer(
    items.indexOf(item), 
    binaryKey
  );

  try {
    const result = await mammoth.extractRawText({ buffer });

    results.push({
      json: {
        fileName: fileName,
        fileContent: result.value
      },
      binary: {
        data: binary[binaryKey]
      }
    });
  } catch (err) {
    results.push({
      json: {
        fileName: fileName,
        fileContent: '',
        error: err.message
      }
    });
  }
}

return results;
